import secrets,json,uuid
from pathlib import Path
if Path('output/design-lab-credentials.json').exists():
 raise SystemExit('Credentials already exist. Keep this file; do not reseed an existing Design Lab.')
owner=str(uuid.uuid4());munshi=str(uuid.uuid4());wid=str(uuid.uuid4());sid=str(uuid.uuid4());ms=str(uuid.uuid4());hsd=str(uuid.uuid4());n1=str(uuid.uuid4());n2=str(uuid.uuid4());account=str(uuid.uuid4());vehicle=str(uuid.uuid4());delivery=str(uuid.uuid4());session=str(uuid.uuid4())
credentials={'owner':{'email':'owner.design@pumpshield.example','password':secrets.token_urlsafe(22)},'munshi':{'email':'munshi.design@pumpshield.example','password':secrets.token_urlsafe(22)}}
queries=['begin;']
for role,uid in [('owner',owner),('munshi',munshi)]:
 c=credentials[role]
 queries.append(f"""insert into auth.users(id,instance_id,email,encrypted_password,email_confirmed_at,aud,role,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change,email_change_token_current,reauthentication_token) values('{uid}','00000000-0000-0000-0000-000000000000','{c['email']}',extensions.crypt('{c['password']}',extensions.gen_salt('bf')),now(),'authenticated','authenticated','{{"provider":"email","providers":["email"]}}','{{}}',now(),now(),'','','','','',''); insert into auth.identities(provider_id,user_id,identity_data,provider,created_at,updated_at)values('{uid}','{uid}','{{"sub":"{uid}","email":"{c['email']}","email_verified":true}}','email',now(),now());""")
queries += [f"insert into public.workspaces(id,name)values('{wid}','PumpShield - Design Lab');",f"insert into public.stations(id,workspace_id,name,omc,city)values('{sid}','{wid}','Clifton Petroleum - Sample','PSO','Karachi');",f"insert into public.memberships(user_id,workspace_id,role,name,station_id)values('{owner}','{wid}','owner','Abdullah - Demo',null),('{munshi}','{wid}','munshi','Adeel - Demo','{sid}');"]
for tid,name,grade,cap,stock in [(ms,'Premier petrol','MS',50000,35000),(hsd,'High-speed diesel','HSD',40000,28000)]:
 chart=json.dumps([{'mm':0,'liters':0},{'mm':1000,'liters':cap/2},{'mm':2000,'liters':cap}])
 queries += [f"insert into public.tanks(id,workspace_id,station_id,name,grade,capacity,stock,chart)values('{tid}','{wid}','{sid}','{name}','{grade}',{cap},{stock},'{chart}');",f"insert into public.prices(workspace_id,station_id,grade,price,beta,margin,effective_at,source)values('{wid}','{sid}','{grade}',{300 if grade=='MS' else 310},{.00115 if grade=='MS' else .00083},10,now()-interval '30 days','SYNTHETIC DESIGN-LAB RATE');"]
for nid,tid,name in [(n1,ms,'Nozzle 01 - Petrol'),(n2,hsd,'Nozzle 02 - Diesel')]:queries.append(f"insert into public.nozzles(id,workspace_id,station_id,tank_id,name,totalizer)values('{nid}','{wid}','{sid}','{tid}','{name}',152400);")
for i,volume in enumerate([8200,7600,9100,8750,10200,9800,11600,10400,8900,9700]):
 result={'liters':volume,'revenue':volume*300,'cash':volume*300-180000,'pos':180000,'credit':0,'expected_cash':volume*300-180000,'cash_variance':0 if i!=0 else -2400,'late':False,'tanks':[{'tank_id':ms,'name':'Premier petrol','grade':'MS','sold':volume,'delivered':0,'expected':35000,'actual':34985 if i==0 else 35000,'variance':-15 if i==0 else 0,'price':300}]}
 queries.append(f"insert into public.shifts(workspace_id,station_id,name,opened_by,opened_at,due_at,closed_at,status,opening,submission,result,review_note) values('{wid}','{sid}','Sample shift {10-i}','{munshi}',now()-interval '{i+1} days',now()-interval '{i+1} days'+interval '12 hours',now()-interval '{i+1} days'+interval '11 hours','{'review' if i==0 else 'verified'}','{{}}','{json.dumps(dict(nozzles=[],tanks=[]))}','{json.dumps(result)}','Synthetic reconciliation for visual review');")
chambers=json.dumps([[{'mm':0,'liters':0},{'mm':1500,'liters':10000}]]*4)
for i,status in enumerate(['dispatched','submitted','approved']):
 did=delivery if i==0 else str(uuid.uuid4());measure='null' if i==0 else json.dumps({'arrival_temp':32,'dips':[1485]*4})
 queries.append(f"insert into public.deliveries(id,workspace_id,station_id,tank_id,reference,vehicle,depot,invoice,loading_temp,price,beta,chambers,status,measured,allowance,shortage,claim,measurement,created_at)values('{did}','{wid}','{sid}','{ms}','SAMPLE-OMC-{1042+i}','TKA-{842+i}','Keamari depot',40000,38,300,.00115,'{chambers}','{status}',{ 'null,null,null,null' if i==0 else '39600,276,124,37200'},'{measure}'::jsonb,now()-interval '{i*4} hours');")
queries += [f"insert into public.accounts(id,workspace_id,station_id,name,credit_limit,balance)values('{account}','{wid}','{sid}','SAMPLE - Atlas Logistics',1500000,480000);",f"insert into public.vehicles(id,workspace_id,account_id,registration,grade,max_liters)values('{vehicle}','{wid}','{account}','SAMPLE-KHI-9921','HSD',200);",f"insert into public.accounts(workspace_id,station_id,name,credit_limit,balance)values('{wid}','{sid}','SAMPLE - Metro Transport',800000,690000),('{wid}','{sid}','SAMPLE - Coastline Textiles',1000000,260000);",f"insert into public.tracking_sessions(id,workspace_id,delivery_id,token_hash,depot_lat,depot_lon,station_lat,station_lon)values('{session}','{wid}','{delivery}','{secrets.token_hex(32)}',24.82,66.97,24.82,67.04);"]
for i,(lat,lon) in enumerate([(24.82,66.97),(24.835,66.98),(24.85,66.99),(24.87,67.005),(24.88,67.02),(24.86,67.035),(24.84,67.04)]):queries.append(f"insert into public.location_reports(session_id,workspace_id,latitude,longitude,accuracy,received_at)values('{session}','{wid}',{lat},{lon},15,now()-interval '{(7-i)*3} minutes');")
queries += [f"insert into public.audit_events(workspace_id,actor_id,action,subject_id)values('{wid}','{owner}','sample_workspace_created','{sid}'),('{wid}','{owner}','synthetic_dispatch_created','{delivery}');",'commit;']
Path('output').mkdir(exist_ok=True);Path('output/design-lab.sql').write_text('\n'.join(queries));Path('output/design-lab-credentials.json').write_text(json.dumps(credentials,indent=2));print('Design Lab fixture generated. Credentials are stored locally under output/.')
